<?php
// Vuosittaiset huoltokustannukset ja arvio ajetuista kilometreistä
$annualCosts=getAnnualCosts($db,(int)$car['id']);
$kmEst=annualKmEstimates(odometerTimelinePoints($db,(int)$car['id']));
$costByYear=[];foreach($annualCosts as $ac)$costByYear[(int)$ac['year']]=(float)$ac['total'];
$yearList=array_unique(array_merge(array_keys($costByYear),array_keys($kmEst['years']??[])));rsort($yearList);
if($yearList):
    $recentYears=array_slice($yearList,0,5);$olderYears=array_slice($yearList,5);
    $yearRow=function(int $y) use($costByYear,$kmEst){
        $cost=$costByYear[$y]??null;$ke=$kmEst['years'][$y]??null;
        $km=$ke?$ke['km']:null;
        $notes=[];if($ke){
            if($ke['project']!==null)$notes[]='vuositahdilla ≈ '.number_format($ke['project'],0,',',' ').' km';
            if($ke['from']!==$y.'-01-01')$notes[]='lukemista alkaen '.fiDate($ke['from']);
            if($ke['to']!==($y+1).'-01-01')$notes[]='viimeisin lukema '.fiDate($ke['to']);
            if($ke['rough'])$notes[]='karkea arvio';
        }
        $note=implode(' · ',$notes);
        ob_start();?>
        <div class="yearrow"><span class="y"><?=h((string)$y)?></span><strong class="c"><?=$cost!==null?h(money($cost)):'–'?></strong><span class="k"><?=$km!==null?'≈ '.h(number_format($km,0,',',' ')).' km':'–'?><?=$ke&&$ke['partial']?' *':''?></span><?php if($note!==''):?><span class="yn tiny"><?=h($note)?></span><?php endif;?></div>
        <?php return ob_get_clean();
    };
?>
<div class="box" style="margin-top: 14px;">
    <strong>Huoltokustannukset ja ajetut kilometrit vuosittain</strong>
    <div class="yearhead"><span>Vuosi</span><span>Huoltokulut</span><span>Ajettu (arvio)</span></div>
    <div style="margin-top: 4px;">
        <?php foreach($recentYears as $yy) echo $yearRow((int)$yy); ?>
        <?php if($olderYears): ?>
            <div id="older-costs-<?= (int)$car['id'] ?>" style="display: none;">
                <?php foreach($olderYears as $yy) echo $yearRow((int)$yy); ?>
            </div>
            <button type="button" class="btn2" style="margin-top: 10px; width: 100%;"
                    onclick="document.getElementById('older-costs-<?= (int)$car['id'] ?>').style.display='block'; this.style.display='none';">
                Näytä vanhemmat
            </button>
        <?php endif; ?>
    </div>
    <?php if(!empty($kmEst['summary'])):$sm=$kmEst['summary'];?>
    <div class="yearsum"><div><span>Keskimäärin</span><strong>≈ <?=h(number_format($sm['per_year'],0,',',' '))?> km / vuosi</strong></div><div class="tiny">Ajanjakso <?=h(fiDate($sm['from']))?> – <?=h(fiDate($sm['to']))?> · <?=h(number_format($sm['km'],0,',',' '))?> km mittarilukemien mukaan</div></div>
    <?php endif;?>
    <div class="tiny" style="margin-top:8px"><?=!empty($kmEst['years'])?'Kilometrit ovat suuntaa antava arvio: ne lasketaan mittarilukemien väliltä tasaisella ajotahdilla, joten tarkkuus paranee, kun lukemia päivitetään tiheästi. * = osittainen vuosi (lukemat eivät kata koko vuotta). Huoltokulut ovat vain kirjatut hinnat, joten ne eivät välttämättä kata kaikkia kuluja.':''?></div>
</div>
<?php endif; ?>

