<div class="kv"><span>Asiakas tapahtumahetkellä</span><span><?=h($s['customer_name_snapshot'])?></span></div><?php endif;?><?php if(!empty($s['service_origin'])):?><div class="kv"><span>Työn alkuperä</span><span><?=h($s['service_origin']==='own'?'Oma työ':($s['service_origin']==='external'?'Ulkopuolinen huolto':'Vanha merkintä'))?></span></div><?php endif;?><?php if(!empty($s['mechanic_name_snapshot'])):?><div class="kv"><span>Mekaanikko</span><span><?=h($s['mechanic_name_snapshot'])?></span></div><?php endif;?><?php if($s['notes']):?><div class="kv"><span>Huomautukset</span><span><?=nl2br(h($s['notes']))?></span></div><?php endif;?><?php if(!empty($s['photos'])):?><div class="kv"><span>Huoltokuvat</span><div><div class="photo-grid"><?php foreach($s['photos'] as $ph):?><div class="photo-card"><a href="<?=h(photoUrl((int)$ph['id'],'original'))?>" target="_blank"><img loading="lazy" src="<?=h(photoUrl((int)$ph['id'],'thumb'))?>" alt="Huoltokuva"></a><?php if(trim((string)($ph['caption']??''))!==''):?><div class="photo-caption"><?=h($ph['caption'])?></div><?php endif;?><div class="photo-tools"><form method="post" class="delete-photo-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete_photo"><input type="hidden" name="car_id" value="<?=$carId?>"><input type="hidden" name="photo_id" value="<?=(int)$ph['id']?>"><button class="danger" type="submit">Poista kuva</button></form></div></div><?php endforeach;?></div></div></div><?php endif;?><div class="form-actions"><a class="btn2" href="?car=<?=$carId?>&edit_service=<?=(int)$s['id']?>#huolto">✏ Muokkaa</a><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>">🖨 Huoltosivu</a><?php if(!empty($s['photos'])):?><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>&photos=1">🖼 Kuvilla</a><?php endif;?><?php if(invoicingEnabled($app)):?><?php if($sinv):?><a class="btn2" href="?invoice=<?=(int)$sinv['id']?>">🧾 Lasku <?=h($s