<section class="section panel" id="varaosat"><div class="sectionhead"><div><div class="eyebrow">Osalaatikko</div><h2>Varaosamuistio<?=inventoryEnabled($app)?' ja varasto':''?></h2><?php if(inventoryEnabled($app)):?><div class="tiny">Saldo muuttuu erillisellä varastotapahtumalla tai huollon yhteydessä vain, jos valitset huoltokohteelle Käytetäänkö varastosta? Kyllä.</div><?php endif;?></div><?php if(inventoryEnabled($app)):?><a class="btn2" href="?view=inventory">📦 Koko varasto</a><?php endif;?></div><?php if($parts):?><div class="partslist"><?php foreach($parts as $p):$stockLow=inventoryEnabled($app)&&$p['reorder_level']!==null&&(float)$p['stock_qty']<=(float)$p['reorder_level'];$compatIds=$partCompatIds[(int)$p['id']]??[(int)$p['car_id']];$compatText=$partCompatText[(int)$p['id']]??'';?><div class="partcard"><h4><?=h($p['part_name'])?></h4><?php if($p['brand']):?><div><?=h($p['brand'])?></div><?php endif;?><?php if($p['supplier_sku']):?><div class="tiny">Varaosanumero: <span class="kbd"><?=h($p['supplier_sku'])?></span></div><?php endif;?><?php if($p['oem_number']):?><div class="tiny">OEM: <span class="kbd"><?=h($p['oem_number'])?></span></div><?php endif;?><?php if($compatText!==''):?><div class="tiny" style="margin-top:5px"><strong>Sopii autoihin:</strong> <?=h($compatText)?><?php if(count($compatIds)>1):?> · <span class="badge">yhteinen osa · yksi saldo</span><?php endif;?></div><?php endif;?><?php if(inventoryEnabled($app)):?><div style="margin:10px 0;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--panel)"><div class="eyebrow">Varastosaldo</div><strong style="font-size:20px"><?=h(dec((float)$p['stock_qty'],2).' '.($p['stock_unit']?:'kpl'))?><?=$stockLow?' ⚠️':''?></strong><?php if($p['shelf_location']):?><div class="tiny">Hyllypaikka: <?=h($p['shelf_location'])?></div><?php endif;?><?php if($p['reorder_level']!==null):?><div class="tiny">Varoitusraja <?=h(dec((float)$p['reorder_level'],2).' '.($p['stock_unit']?:'kpl'))?></div><?php